import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.BbSdnUwJ.js";const u=JSON.parse('{"title":"What the compiler checks","description":"The validation rules the compiler runs on the assembled robot and its task, what each answer means, and what to do when a rule fails or cannot decide.","frontmatter":{"title":"What the compiler checks","description":"The validation rules the compiler runs on the assembled robot and its task, what each answer means, and what to do when a rule fails or cannot decide."},"headers":[],"relativePath":"guide/advanced/validation.md","filePath":"guide/advanced/validation.md"}'),d={name:"guide/advanced/validation.md"};function r(n,e,h,i,c,l){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="what-the-compiler-checks" tabindex="-1">What the compiler checks <a class="header-anchor" href="#what-the-compiler-checks" aria-label="Permalink to &quot;What the compiler checks&quot;">​</a></h1><p>After it has assembled the robot, the compiler runs its validation rules. Each rule asks one question of the facts it derived, such as where each wheel touches the ground or where the centre of mass is, and answers with the evidence it used.</p><table tabindex="0"><thead><tr><th>Answer</th><th>Means</th></tr></thead><tbody><tr><td><code>pass</code></td><td>The facts settle the question in the program&#39;s favour</td></tr><tr><td><code>fail</code></td><td>They settle it against: an error, and nothing is written</td></tr><tr><td><code>unknown</code></td><td>They do not settle it, usually because a part does not state something: a warning, never a pass</td></tr><tr><td><code>not_applicable</code></td><td>The question does not arise, such as steering on a base that does not steer</td></tr></tbody></table><p><code>--json</code> lists every rule with its answer and evidence.</p><h2 id="assembly" tabindex="-1">Assembly <a class="header-anchor" href="#assembly" aria-label="Permalink to &quot;Assembly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Asks</th></tr></thead><tbody><tr><td><code>assembly.glue_on_connector</code></td><td>Does every part&#39;s glue name a connector of the chassis?</td></tr><tr><td><code>assembly.one_part_per_connector</code></td><td>Does each connector carry at most one part?</td></tr><tr><td><code>assembly.wheel_mounts_filled</code></td><td>Does every wheel mount carry exactly one driven wheel, and no driven wheel sit elsewhere?</td></tr><tr><td><code>assembly.wheel_type_matches_chassis</code></td><td>Is every driven wheel of a type the chassis takes?</td></tr><tr><td><code>assembly.steering_declared</code></td><td>Does each steered mount carry an upright kingpin?</td></tr><tr><td><code>assembly.axles_horizontal</code></td><td>Is every driven wheel&#39;s axle horizontal?</td></tr><tr><td><code>assembly.wheels_touch_one_plane</code></td><td>Do all wheels touch the ground within 2 mm of one plane?</td></tr><tr><td><code>assembly.footprint_known</code></td><td>Do the parts&#39; collision boxes bound the robot&#39;s footprint?</td></tr></tbody></table><h2 id="statics" tabindex="-1">Statics <a class="header-anchor" href="#statics" aria-label="Permalink to &quot;Statics&quot;">​</a></h2><p><code>statics.mass_inside_the_wheel_contacts</code> asks whether the robot stands. The centre of mass must fall strictly inside the polygon of the ground contacts: the wheels, and the skids and balls the parts declare under <code>contacts</code> that reach the wheels&#39; plane.</p><ul><li>Outside the polygon, or on its edge, is a <code>fail</code>: at rest the robot tips until something else touches the ground.</li><li>A declared skid or ball that reaches below the wheels&#39; plane is a <code>fail</code> too: the robot stands on it and tips off its wheels.</li><li>Two wheels and nothing else lie on one line and settle nothing, so the answer is <code>unknown</code>. The chassis may have a skid its part file does not declare, and the warning asks for it, or for a caster.</li></ul><h2 id="kinematics" tabindex="-1">Kinematics <a class="header-anchor" href="#kinematics" aria-label="Permalink to &quot;Kinematics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Asks</th></tr></thead><tbody><tr><td><code>kinematics.omni_wheels_span_the_plane</code></td><td>Can an omni base&#39;s wheels together produce every planar motion?</td></tr><tr><td><code>kinematics.spin_supported</code></td><td>If the task spins in place, can the base?</td></tr><tr><td><code>kinematics.strafe_supported</code></td><td>If the task strafes, is the base holonomic?</td></tr></tbody></table><h2 id="what-a-clean-check-does-not-establish" tabindex="-1">What a clean check does not establish <a class="header-anchor" href="#what-a-clean-check-does-not-establish" aria-label="Permalink to &quot;What a clean check does not establish&quot;">​</a></h2><p>A clean check means every name exists, every argument is well typed, every reference resolves, every part mates onto a real connector, and the rules pass on what the libraries state. It does not establish that the robot spawns, drives, or completes the task. That is observed when the output runs, and <a href="./judging-a-run.html">judged from the simulator&#39;s own record</a>.</p><p><a href="./../../reference/validation.html">Validation rules</a> in the reference is generated from the rules themselves.</p>',14)])])}const p=t(d,[["render",r]]);export{u as __pageData,p as default};
